/* Three form workflows share a preview, but entry and review use separate actions. */
(()=>{
const words={sfbLimit:['火源清單已達300筆查詢上限，為避免遺漏，本次未執行。請使用原火源表單處理較舊月份。','Fire list reached the 300-record limit. Nothing was processed to avoid omissions; use the original form for older months.','La lista alcanzó el límite de 300 registros. No se procesó nada; use el formulario original para meses antiguos.','Danh sách nguồn lửa đạt giới hạn 300 bản ghi. Chưa xử lý để tránh thiếu sót; dùng biểu mẫu gốc cho tháng cũ.'],
supervisorFormBatch:['起重機／火源批次點檢與審核','Crane / fire batch inspection and approval','Inspección y aprobación por lote: grúas / fuego','Kiểm tra và duyệt hàng loạt: cầu trục / nguồn lửa'],
sfbForm:['選擇表單','Form','Formulario','Biểu mẫu'],sfbFire:['日常火源自行檢查表','Daily fire-source inspection','Inspección diaria de fuentes de fuego','Kiểm tra nguồn lửa hằng ngày'],
sfbCycle:['週期','Cycle','Frecuencia','Chu kỳ'],sfbDaily:['每日','Daily','Diaria','Hằng ngày'],sfbWeekly:['每週（起日每隔7天）','Weekly (every 7 days from start)','Semanal (cada 7 días desde el inicio)','Hằng tuần (mỗi 7 ngày từ ngày đầu)'],sfbMonthly:['每月','Monthly','Mensual','Hằng tháng'],
sfbHelp:['填報與審核分開執行。每日／每週區間最多31天，月檢表最多367天。已有起重機紀錄會跳過；火源表只填所選日期的空白，保留既有結果與備註。','Entry and review are separate. Daily/weekly ranges: up to 31 days; monthly: 367 days. Existing crane records are skipped. Fire entry fills selected blanks and retains results and notes.','Registro y aprobación separados. Intervalos diarios/semanales: 31 días; mensuales: 367. Se omiten registros de grúa existentes. Solo se completan vacíos seleccionados en fuego, conservando resultados y notas.','Nhập và duyệt riêng. Khoảng ngày/tuần tối đa 31 ngày; tháng 367 ngày. Bỏ qua bản ghi cầu trục đã có; bảng nguồn lửa chỉ điền ô trống đã chọn và giữ kết quả, ghi chú.'],
sfbFireHelp:['火源表以部門、負責區域及月份分張。填滿截至今日／月底的所有日期才送審，其餘儲存草稿；主管審核以整張月表為單位。','Fire sheets are grouped by department, area and month. Submit only when complete through today/month end; otherwise save as draft. Review approves the entire monthly sheet.','Las hojas de fuego se agrupan por departamento, área y mes. Solo se envían completas hasta hoy/fin de mes; el resto queda como borrador. Se aprueba la hoja mensual completa.','Bảng nguồn lửa chia theo bộ phận, khu vực và tháng. Chỉ gửi duyệt khi đủ đến hôm nay/cuối tháng; còn lại lưu nháp. Duyệt toàn bộ bảng tháng.'],
sfbArea:['負責區域（火源表填報必填）','Responsible area (required for fire entry)','Área responsable (obligatoria para registrar fuego)','Khu vực phụ trách (bắt buộc khi nhập nguồn lửa)'],
sfbConfirmEntry:['我確認所選設備／區域在所選日期均已實際檢查，空白項目可填入合格。','I confirm actual inspections on all selected dates; blank items may be recorded as passing.','Confirmo inspecciones reales en las fechas seleccionadas; los vacíos pueden registrarse conformes.','Tôi xác nhận đã kiểm tra thực tế mọi ngày đã chọn; có thể điền đạt vào ô trống.'],
sfbConfirmReview:['我已查核所選表單完整內容與異常處理，確認簽核。','I reviewed all selected sheets and exception handling and confirm approval.','Revisé las hojas y el tratamiento de incidencias; confirmo la aprobación.','Tôi đã kiểm tra toàn bộ bảng đã chọn và xử lý bất thường, xác nhận duyệt.'],
sfbMeasurement:['鋼索實測（逐台輸入，mm）','Rope measurements (per machine, mm)','Medición del cable (por máquina, mm)','Đo cáp thực tế (từng máy, mm)'],
sfbInvalid:['請確認有效日期、姓名、勾選清單與實際查核確認；月檢表需逐台填鋼索實測，火源表需負責區域。','Check dates, name, selected rows and actual-review confirmation. Monthly entry requires rope measurements per machine; fire entry requires an area.','Revise fechas, nombre, selección y confirmación. La entrada mensual exige mediciones por máquina; fuego exige área.','Kiểm tra ngày, tên, lựa chọn và xác nhận thực tế. Nhập tháng cần số đo cáp từng máy; nguồn lửa cần khu vực.'],
sfbReady:['可處理','Ready','Disponible','Có thể xử lý'],sfbSkip:['已有紀錄／狀態不符／待改善，排除','Existing / ineligible / unresolved; excluded','Existente / no elegible / pendiente; excluido','Đã có / không hợp lệ / chưa xử lý; loại trừ'],sfbSubmitted:['已送主管審核','Submitted for review','Enviado a aprobación','Đã gửi quản lý duyệt'],sfbDraft:['已存草稿，尚未填滿整月','Draft saved; month incomplete','Borrador guardado; mes incompleto','Đã lưu nháp; tháng chưa đầy đủ'],
sfbLoading:['正在讀取表單清單…','Loading sheets…','Cargando hojas…','Đang tải danh sách…'],sfbFailure:['部分未完成；請重新讀取清單核對後重試。','Some entries are incomplete. Reload and check before retrying.','Hay registros incompletos. Recargue y revise antes de reintentar.','Một số mục chưa xong. Tải lại và kiểm tra trước khi thử lại.'],
sfbDetails:['查核結果','Inspection results','Resultados','Kết quả kiểm tra'],sfbSignature:['審核簽名（火源表）','Review signature (fire sheet)','Firma de aprobación (fuego)','Chữ ký duyệt (nguồn lửa)'],sfbSubmit:['一鍵執行所選表單','Process selected sheets','Procesar hojas seleccionadas','Thực hiện các bảng đã chọn']
};for(const[k,v]of Object.entries(words))translations[k]=Object.fromEntries(['zh','en','es','vi'].map((l,i)=>[l,v[i]]));
const R=window.SupervisorBatchRules;
let scope='',mode='entry',form='daily',cycle='daily',dept='',start='',end='',area='',inspector='',reviewer='',signature='',note='',rows=[],loaded=false,busy=false,ticket=0,message='';
const key=()=>activeCountry+':'+countryGeneration+':'+profile?.account_id;
const resource=()=>form==='monthly'?'crane_monthly':'crane_daily';
function departments(){return data.departments.filter(d=>d.is_active!==false&&(form==='fire'?(profile.role==='admin'||(data.access?.managed?data.access.grants.some(g=>g.department_id===d.id):d.id===profile.department_id)):(accessCan(d.id,resource(),'view')&&accessCan(d.id,resource(),mode==='entry'?'create':'approve')&&(mode==='entry'||accessCan(d.id,resource(),'edit')))));}
const title=()=>form==='fire'?'sfbFire':form==='monthly'?'craneMonthly':'craneDaily';
const previousContent=renderContent;renderContent=function(){if(view!=='supervisorFormBatch')return previousContent();if(!canManage()||!activeCountry){$('#content').innerHTML=txt('accessNoRights');return;}draw();};
const previousRender=render;render=function(){previousRender();if(!canManage()||!activeCountry)return;const parent=$('.side details[data-section="supervisor"] .nav-section-items');if(!parent)return;const b=document.createElement('button');b.className='nav'+(view==='supervisorFormBatch'?' active':'');b.dataset.view='supervisorFormBatch';b.innerHTML='▶ '+txt('supervisorFormBatch');b.onclick=()=>{view='supervisorFormBatch';render();};parent.append(b);if(view==='supervisorFormBatch')parent.parentElement.open=true;};
function draw(){
 if(scope!==key()){scope=key();dept='';start=inspectionDay();end=start;rows=[];loaded=false;message='';ticket++;}
 $('.page-title h1').innerHTML=txt('supervisorFormBatch');
 $('#content').innerHTML=`<div role="tablist" class="filter-row">${[['entry','cbEntry'],['review','cbReview']].map(([value,label])=>`<button role="tab" aria-selected="${mode===value}" class="btn ${mode===value?'primary':'secondary'}" data-sfb-mode="${value}">${txt(label)}</button>`).join('')}</div><p class="notice">${txt('sfbHelp')}</p>${form==='fire'?`<p class="notice">${txt('sfbFireHelp')}</p>`:''}<div class="editor-fields"><label>${txt('sfbForm')}<select class="select" id="sfbForm">${[['daily','craneDaily'],['monthly','craneMonthly'],['fire','sfbFire']].map(([v,k])=>`<option value="${v}" ${v===form?'selected':''}>${esc(t(k))}</option>`).join('')}</select></label><label>${txt('department')}<select class="select" id="sfbDept"><option value="">${t('all')}</option>${departments().map(d=>`<option value="${esc(d.id)}" ${d.id===dept?'selected':''}>${esc(nameOf(d))}</option>`).join('')}</select></label><label>${txt('sfbCycle')}<select class="select" id="sfbCycle">${(form==='monthly'?['monthly']:['daily','weekly']).map(c=>`<option value="${c}" ${cycle===c?'selected':''}>${t({daily:'sfbDaily',weekly:'sfbWeekly',monthly:'sfbMonthly'}[c])}</option>`).join('')}</select></label><label>${txt('batchRangeStart')}<input id="sfbStart" class="select" type="date" value="${start}" max="${inspectionDay()}"></label><label>${txt('batchRangeEnd')}<input id="sfbEnd" class="select" type="date" value="${end}" max="${inspectionDay()}"></label>${form==='fire'?`<label>${txt('sfbArea')}<input id="sfbArea" class="select" maxlength="200" value="${esc(area)}"></label>`:''}<label>${txt(mode==='entry'?'inspector':'reviewerName')}<input id="sfbName" class="select" maxlength="100" value="${esc(mode==='entry'?inspector:reviewer)}"></label>${mode==='review'?`${form==='fire'?`<label>${txt('reviewNote')}<textarea id="sfbNote" maxlength="2000">${esc(note)}</textarea></label>`:''}${form==='fire'?`<label>${txt('sfbSignature')}<input id="sfbSignature" class="select" maxlength="100" value="${esc(signature)}"></label>`:''}`:''}</div><button id="sfbLoad" class="btn secondary">${txt('batchPreview')}</button><p id="sfbStatus" role="status">${esc(message)}</p>${loaded?`<label><input id="sfbAll" type="checkbox" checked>${txt('batchSelectAll')}</label><div class="table-wrap"><table class="matrix"><thead><tr><th></th><th>${txt('department')}</th><th>${txt('inspectionDate')}</th><th>${txt('equipmentCode')} / ${txt('fireArea')}</th><th>${txt('sfbDetails')}</th>${mode==='entry'&&form==='monthly'?`<th>${txt('sfbMeasurement')}</th>`:''}<th>${txt('status')}</th></tr></thead><tbody>${rows.map((r,i)=>`<tr><td><input type="checkbox" data-sfb-row="${i}" ${r.eligible?'checked':'disabled'} aria-label="${esc(r.label+' '+r.date)}"></td><td>${esc(nameOf(data.departments.find(d=>d.id===r.department)))}</td><td>${esc(r.date)}</td><td>${esc(r.label)}</td><td><details><summary>${esc(t(title()))}</summary>${resultSummary(r)}</details></td>${mode==='entry'&&form==='monthly'?`<td>${r.eligible&&r.items.some(x=>Number(x.id)===7)?`<label>10 mm<input class="select" type="number" min="0.01" step="0.01" data-sfb-measure="${i}:10" value="${esc(r.m10||'')}"></label><label>12 mm<input class="select" type="number" min="0.01" step="0.01" data-sfb-measure="${i}:12" value="${esc(r.m12||'')}"></label>`:'—'}</td>`:''}<td>${esc(r.outcome||t(r.eligible?'sfbReady':'sfbSkip'))}</td></tr>`).join('')}</tbody></table></div><label><input id="sfbActual" type="checkbox">${txt(mode==='entry'?'sfbConfirmEntry':'sfbConfirmReview')}</label>${powerCheckButton('sfbSubmit','id="sfbSubmit"')}`:''}`;
 for(const el of $$('[data-sfb-mode]'))el.onclick=()=>{if(busy)return;mode=el.dataset.sfbMode;dept='';invalidate();};
 $('#sfbForm').onchange=e=>{form=e.target.value;cycle=form==='monthly'?'monthly':'daily';dept='';invalidate();};
 for(const [id,set]of [['sfbDept',v=>dept=v],['sfbCycle',v=>cycle=v],['sfbStart',v=>start=v],['sfbEnd',v=>end=v],['sfbArea',v=>area=v]])if($('#'+id))$('#'+id).onchange=e=>{set(e.target.value);invalidate();};
 if($('#sfbArea'))$('#sfbArea').oninput=e=>{area=e.target.value;loaded=false;ticket++;if($('#sfbSubmit'))$('#sfbSubmit').disabled=true;};
 $('#sfbName').oninput=e=>{if(mode==='entry')inspector=e.target.value;else reviewer=e.target.value;};if($('#sfbNote'))$('#sfbNote').oninput=e=>note=e.target.value;if($('#sfbSignature'))$('#sfbSignature').oninput=e=>signature=e.target.value;
 $('#sfbLoad').onclick=preview;if(loaded){$('#sfbAll').onchange=e=>{$$('[data-sfb-row]:not(:disabled)').forEach(x=>x.checked=e.target.checked);$('#sfbActual').checked=false;};$$('[data-sfb-row]').forEach(x=>x.onchange=()=>$('#sfbActual').checked=false);$$('[data-sfb-measure]').forEach(x=>x.oninput=e=>{const [index,size]=e.target.dataset.sfbMeasure.split(':');rows[+index]['m'+size]=e.target.value;$('#sfbActual').checked=false;});$('#sfbSubmit').onclick=submit;$('#sfbSubmit').disabled=!rows.some(r=>r.eligible);}
 if(busy)$('#content').querySelectorAll('input,select,textarea,button').forEach(x=>x.disabled=true);
}
function invalidate(){rows=[];loaded=false;message='';ticket++;draw();}
function resultSummary(r){if(form==='fire')return `<p>${esc(r.record?.status||'draft')}</p><p>${esc((r.record?.entries||[]).map(e=>e.day+': '+R.fields.map(k=>e[k]||'—').join(' / ')+(e.note?' · '+e.note:'')).join('\n'))}</p>`;return `<ol>${r.items.map((i,n)=>`<li>${formContentHtml(i.name)}：${esc(r.record?.results?.[n]?.value||'—')}</li>`).join('')}</ol>`;}
async function preview(){
 if(busy||!canManage())return;dept=$('#sfbDept').value;start=$('#sfbStart').value;end=$('#sfbEnd').value;cycle=$('#sfbCycle').value;if($('#sfbArea'))area=$('#sfbArea').value;let dates;try{dates=R.dates(start,end,inspectionDay(),cycle);if(form==='fire'&&mode==='entry'&&!area.trim())throw Error('area');}catch{message=t('sfbInvalid');draw();return;}
 const own=key(),n=++ticket,ds=departments().filter(d=>!dept||d.id===dept);busy=true;rows=[];loaded=false;message=t('sfbLoading');draw();
 try{const result=[];if(form==='fire'){
  const response=await api({action:'fire_daily_list'});if(own!==key()||n!==ticket)return;if(response.records.length>=300)throw Error('batch_list_limit');response.records=response.records.filter(r=>r.inspection_month.slice(0,7)>=start.slice(0,7)&&r.inspection_month.slice(0,7)<=end.slice(0,7));
  if(mode==='review'){for(const r of response.records.filter(r=>ds.some(d=>d.id===r.department_id)&&(!area.trim()||r.responsible_area===area.trim())))result.push({department:r.department_id,date:r.inspection_month.slice(0,7),label:r.responsible_area,record:r,eligible:R.fireReady(r,inspectionDay())});}
  else for(const d of ds)for(const month of R.months(dates)){const r=response.records.find(r=>r.department_id===d.id&&r.inspection_month.slice(0,7)===month&&r.responsible_area===area.trim())||newFireRecord(d.id,month);let eligible=true;try{R.fillFire(r,dates,inspector.trim()||'preview',inspectionDay());}catch{eligible=false;}result.push({department:d.id,date:month,label:area.trim(),record:r,dates:dates.filter(x=>x.startsWith(month)),eligible});}
 }else{
  const machines=data.equipment.filter(e=>!e.archived_at&&e.machine_no&&ds.some(d=>d.id===e.department_id)&&/天車|起重機/.test(e.name_zh+' '+(e.equipment_groups?.name_zh||data.groups.find(g=>g.id===e.equipment_group_id)?.name_zh||'')));
  for(const e of machines)for(const month of R.months(dates)){const response=await api({action:'crane_month',equipment_id:e.id,kind:form,month});if(own!==key()||n!==ticket)return;
   const periods=form==='monthly'?[dates.filter(d=>d.startsWith(month)).at(-1)]:dates.filter(d=>d.startsWith(month));
   for(const date of periods){const r=response.records.find(r=>form==='monthly'||r.inspection_date===date),items=form==='monthly'?(r?.template_snapshot||response.template?.items||CRANE_TEMPLATE.monthly.items):CRANE_TEMPLATE.daily.items;
    result.push({equipment:e,department:e.department_id,date:mode==='review'&&r?r.inspection_date:date,label:e.machine_no,record:r,items,templateRevision:r?.template_revision??response.template?.revision??0,eligible:mode==='entry'?!r:R.craneReady(r,form,items)});
   }
  }
 }
 if(own===key()&&n===ticket){rows=result;loaded=true;message=t('sfbReady')+'：'+rows.filter(r=>r.eligible).length+' / '+rows.length;}
 }catch(e){if(own===key()&&n===ticket)message=t(e.message==='batch_list_limit'?'sfbLimit':'sfbFailure');}finally{busy=false;if(own===key()&&view==='supervisorFormBatch')draw();}
}
function newFireRecord(department,month){return {id:crypto.randomUUID(),department_id:department,inspection_month:month,responsible_area:area.trim(),implementer_name:'',entries:Array.from({length:new Date(Number(month.slice(0,4)),Number(month.slice(5)),0).getDate()},(_,i)=>({day:i+1,fire_use:'',electrical_wiring:'',cigarette:'',shutdown_fire:'',combustibles:'',note:''})),status:'draft',updated_at:null};}
function payload(r){
 if(form==='fire'){if(mode==='entry')return {action:'fire_daily_save',record:R.fillFire(r.record,r.dates,inspector.trim(),inspectionDay())};return {action:'fire_daily_review',id:r.record.id,updated_at:r.record.updated_at,manager_name:reviewer.trim(),manager_disposition:note.trim(),manager_signature:signature.trim(),decision:'confirm'};}
 const old=r.record,results=mode==='review'?old.results:r.items.map(i=>({id:i.id,value:form==='daily'?'ˇ':'✔',...(form==='monthly'&&Number(i.id)===7?{diameter_measurements:{10:r.m10||'',12:r.m12||''}}:{})}));
 return {action:'crane_save',equipment_id:r.equipment.id,kind:form,inspection_date:r.date,revision:old?.revision||0,template_revision:r.templateRevision,results,details:old?.details||(form==='daily'?{location:r.equipment.location||'',measures:''}:{model:'',capacity:'',hazard:'',risk:'',measures:'',suitability:''}),inspector_name:old?.inspector_name||inspector.trim(),leader_name:old?.leader_name||'',supervisor_name:mode==='review'?reviewer.trim():'',completed:true,confirmed:mode==='review'};
}
async function submit(){
 if(busy||!loaded||!canManage())return;const selected=$$('[data-sfb-row]:checked').map(x=>rows[+x.dataset.sfbRow]).filter(r=>r?.eligible),person=(mode==='entry'?inspector:reviewer).trim();
 const needsMeasurements=mode==='entry'&&form==='monthly'&&selected.some(r=>r.items.some(i=>Number(i.id)===7)&&(![r.m10,r.m12].some(v=>String(v||'').trim())||[r.m10,r.m12].some(v=>String(v||'').trim()&&(!Number.isFinite(Number(v))||Number(v)<=0))));
 if(!selected.length||!person||!$('#sfbActual').checked||needsMeasurements||(mode==='review'&&form==='fire'&&(!note.trim()||!signature.trim()))){message=t('sfbInvalid');$('#sfbStatus').textContent=message;return;}
 const own=key();busy=true;countryBusy++;let done=0,skipped=0,failed=0;draw();
 try{for(const r of selected){if(own!==key())break;try{const p=payload(r);await api(p);r.eligible=false;r.outcome=form==='fire'&&mode==='entry'?t(p.record.status==='draft'?'sfbDraft':'sfbSubmitted'):t('batchDone');done++;}
  catch(e){if(['record_changed','template_changed','equipment_changed','fire_daily_locked','fire_daily_exists','not_qualified'].includes(e.message)){r.eligible=false;r.outcome=t('sfbSkip');skipped++;}else{r.outcome=t('sfbFailure');failed++;break;}}
  message=t('batchDone')+'：'+done+'；'+t('batchSkipped')+'：'+skipped+'；'+t('batchPending')+'：'+(selected.length-done-skipped);if(own===key()&&view==='supervisorFormBatch')$('#sfbStatus').textContent=message;
 }}finally{countryBusy--;busy=false;if(own===key()){message=t('batchDone')+'：'+done+'；'+t('batchSkipped')+'：'+skipped+'；'+t('batchPending')+'：'+(selected.length-done-skipped)+(failed?' — '+t('sfbFailure'):'');if(view==='supervisorFormBatch')draw();}}
}
if(profile&&activeCountry)render();
})();
